    /**
     * @param  array<string, string>  $texts
     */
    private function apply(array $texts): void
    {
        DB::transaction(function () use ($texts): void {
            foreach ($texts as $slug => $text) {
                $article = DB::table('theory_articles')->where('slug', $slug)->first();

                if ($article === null) {
                    continue;
                }

                $task = json_decode((string) $article->task, true);

                if (! is_array($task)) {
                    continue;
                }

                $task['text'] = $text;

                DB::table('theory_articles')->where('id', $article->id)->update([
                    'task' => json_encode($task, JSON_UNESCAPED_UNICODE),
                ]);
            }
        });
    }

